/* Meus Sonhos & Metas · edição experimental 2.0
   Dados pessoais e arquivos permanecem no IndexedDB deste navegador.
   Não há sincronização em nuvem nesta versão. */
(()=>{'use strict';
const NAV=[['inicio','Início','🏡'],['perfil','Meu perfil','👩🏻'],['rotina','Minha rotina','📅'],['biblia','Ler a Bíblia','📖'],['plano','Plano bíblico','🕊️'],['biblioteca','Minha biblioteca','📚'],['caderno','Caderno de anotações','📝'],['mural','Mural dos sonhos','🌸'],['progresso','Meu progresso','📊'],['ajustes','Ajustes e backups','⚙️']];
const CATS=['Estudos','Espiritualidade','Saúde','Trabalho','Casa','Finanças','Pessoal','Outros'];
const ICONS={Estudos:'📚',Espiritualidade:'🕊️',Saúde:'🌿',Trabalho:'💼',Casa:'🏡',Finanças:'💰',Pessoal:'✨',Outros:'🌷'};
const VERSIONS=[['alm1911','Almeida 1911 (domínio público)'],['almeida-livre','Bíblia Livre — Almeida 1819'],['bpm','Bíblia Portuguesa Mundial'],['blpt','Bíblia Livre Para Todos (NT)'],['nva','Nova Versão de Acesso Livre'],['onbv','Open Nova Bíblia Viva'],['tft','Tradução para Tradutores (NT)']];
const B=[['Gênesis','genesis',50],['Êxodo','exodus',40],['Levítico','leviticus',27],['Números','numbers',36],['Deuteronômio','deuteronomy',34],['Josué','joshua',24],['Juízes','judges',21],['Rute','ruth',4],['1 Samuel','1-samuel',31],['2 Samuel','2-samuel',24],['1 Reis','1-kings',22],['2 Reis','2-kings',25],['1 Crônicas','1-chronicles',29],['2 Crônicas','2-chronicles',36],['Esdras','ezra',10],['Neemias','nehemiah',13],['Ester','esther',10],['Jó','job',42],['Salmos','psalms',150],['Provérbios','proverbs',31],['Eclesiastes','ecclesiastes',12],['Cânticos','song-of-solomon',8],['Isaías','isaiah',66],['Jeremias','jeremiah',52],['Lamentações','lamentations',5],['Ezequiel','ezekiel',48],['Daniel','daniel',12],['Oseias','hosea',14],['Joel','joel',3],['Amós','amos',9],['Obadias','obadiah',1],['Jonas','jonah',4],['Miqueias','micah',7],['Naum','nahum',3],['Habacuque','habakkuk',3],['Sofonias','zephaniah',3],['Ageu','haggai',2],['Zacarias','zechariah',14],['Malaquias','malachi',4],['Mateus','matthew',28],['Marcos','mark',16],['Lucas','luke',24],['João','john',21],['Atos','acts',28],['Romanos','romans',16],['1 Coríntios','1-corinthians',16],['2 Coríntios','2-corinthians',13],['Gálatas','galatians',6],['Efésios','ephesians',6],['Filipenses','philippians',4],['Colossenses','colossians',4],['1 Tessalonicenses','1-thessalonians',5],['2 Tessalonicenses','2-thessalonians',3],['1 Timóteo','1-timothy',6],['2 Timóteo','2-timothy',4],['Tito','titus',3],['Filemom','philemon',1],['Hebreus','hebrews',13],['Tiago','james',5],['1 Pedro','1-peter',5],['2 Pedro','2-peter',3],['1 João','1-john',5],['2 João','2-john',1],['3 João','3-john',1],['Judas','jude',1],['Apocalipse','revelation',22]];
const today=()=>{let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const shortDate=v=>{if(!v)return '—';const [a,b,c]=v.split('-');return `${c}/${b}/${a}`};
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const uid=()=>crypto.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const formatMin=m=>{m=Math.max(0,Math.round(Number(m)||0));return m>=60?`${Math.floor(m/60)}h${m%60?` ${m%60}min`:''}`:`${m}min`};
const defaultState=()=>({version:2,profile:{name:'',quote:'Não existe mudança sem constância. 🌷',avatar:null,cover:null},routines:[],logs:[],slides:[],dreams:[],notes:[],books:[],bible:{version:'alm1911',book:'acts',chapter:15,plan:{'2026-11-23':{book:'acts',from:15,to:16}},read:[]},legacy:null,createdAt:new Date().toISOString()});
let S=defaultState(),DB=null,section='inicio',selectedRoutine=null,selectedDate=today(),chosenBibleDay=today(),bibleBook='acts',bibleChapter=15,planFlow=null,activeBook=null,slideIndex=0,slideTimer=null,imageUrls=[],currentPdfDoc=null,currentRendition=null,ebookObj=null,importedBookId=null;const $=s=>document.querySelector(s);
function toast(txt){let t=$('#toast');t.textContent=txt;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,3900)}
function tx(store,mode='readonly'){return DB.transaction(store,mode).objectStore(store)}
function reqPromise(req){return new Promise((ok,no)=>{req.onsuccess=()=>ok(req.result);req.onerror=()=>no(req.error)})}
async function initDB(){return new Promise((res,rej)=>{let r=indexedDB.open('meus-sonhos-metas-v2',1);r.onupgradeneeded=()=>{let db=r.result;if(!db.objectStoreNames.contains('kv'))db.createObjectStore('kv');if(!db.objectStoreNames.contains('assets'))db.createObjectStore('assets')};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function loadState(){DB=await initDB();let data=await reqPromise(tx('kv').get('main'));if(data&&typeof data==='object'){S={...defaultState(),...data};S.profile={...defaultState().profile,...(data.profile||{})};S.bible={...defaultState().bible,...(data.bible||{})}}S.routines||=[];S.logs||=[];S.slides||=[];S.dreams||=[];S.notes||=[];S.books||=[]}
let saveQueue=Promise.resolve();function persist(){saveQueue=saveQueue.catch(()=>{}).then(async()=>{await reqPromise(tx('kv','readwrite').put(S,'main'))}).catch(e=>toast('Não foi possível salvar: '+e.message));return saveQueue}
async function storeAsset(file){if(!file)return null;if(file.size>80*1024*1024)throw Error('Arquivo acima de 80 MB. Use arquivos menores.');let id=uid();await reqPromise(tx('assets','readwrite').put({blob:file,name:file.name||'arquivo',type:file.type||''},id));return id}
async function getAsset(id){return id?reqPromise(tx('assets').get(id)):null}
function dropUrls(){imageUrls.forEach(x=>URL.revokeObjectURL(x));imageUrls=[]}
async function hydrateImages(root=document){let els=[...root.querySelectorAll('[data-asset]')];await Promise.all(els.map(async el=>{try{let a=await getAsset(el.dataset.asset);if(a?.blob){let u=URL.createObjectURL(a.blob);imageUrls.push(u);if(el.tagName==='IMG')el.src=u;else el.style.backgroundImage=`url("${u}")`}}catch(e){}}))}
function navHTML(mobile=false){return (mobile?NAV.filter(x=>['inicio','rotina','plano','biblioteca','caderno','perfil'].includes(x[0])):NAV).map(([id,title,icon])=>`<button type="button" data-nav="${id}" class="${mobile?'':'navlink '}${id===section?'active':''}"><span class="ni">${icon}</span>${mobile?`<span>${title.replace('Minha ','').replace('Meu ','')}</span>`:`<span>${title}</span>`}</button>`).join('')}
function render(){if(slideTimer)clearInterval(slideTimer);if(currentRendition){try{currentRendition.destroy()}catch{}currentRendition=null}dropUrls();$('#sideNav').innerHTML=navHTML(false);$('#mobileNav').innerHTML=navHTML(true);const p=NAV.find(x=>x[0]===section)||NAV[0];$('#topSub').textContent=section==='inicio'?'UM PASSO DE CADA VEZ':'SEU ESPAÇO PESSOAL';$('#topTitle').textContent=p[1];let avatar=$('#headerAvatar');avatar.textContent=(S.profile.name||'J').charAt(0).toUpperCase();avatar.removeAttribute('data-asset');if(S.profile.avatar){avatar.innerHTML=`<img alt="Foto de perfil" data-asset="${esc(S.profile.avatar)}">`}
 const map={inicio:home,perfil:profile,rotina:routines,biblia:bibleView,plano:planView,biblioteca:library,caderno:notebook,mural:dreams,progresso:progressView,ajustes:settings};$('#view').innerHTML=map[section]();hydrateImages();if(section==='inicio')startSlides();if(section==='biblia')loadBibleText();if(section==='plano'&&planFlow)loadBibleText();}
function go(id){if(!NAV.some(n=>n[0]===id))return;section=id;render();window.scrollTo({top:0,behavior:'smooth'})}
function cardEmpty(icon,title,info,btn,action){return `<div class="empty"><span class="em">${icon}</span><strong>${esc(title)}</strong><p>${esc(info)}</p>${btn?`<button class="btn light" data-action="${action}">${esc(btn)}</button>`:''}</div>`}
function progressLine(num){return `<div class="progress"><div style="width:${Math.min(100,Math.max(0,num))}%"></div></div>`}
function getDayLogs(id,date=today()){return S.logs.filter(l=>l.routineId===id&&l.date===date)}
function totalMins(id,date=null){return S.logs.filter(l=>l.routineId===id&&(!date||l.date===date)).reduce((a,v)=>a+(Number(v.minutes)||0),0)}
function dayPct(r,date=today()){return r.targetMinutes>0?Math.round(100*totalMins(r.id,date)/r.targetMinutes):getDayLogs(r.id,date).length?100:0}
function stats(){return {minutes:S.logs.filter(l=>l.date===today()).reduce((a,l)=>a+Number(l.minutes||0),0),logs:S.logs.filter(l=>l.date===today()).length,books:S.books.filter(b=>b.status==='lendo').length,read:S.bible.read.length}}
const welcomeSlides=[{icon:'🏡',title:'Meu sonho da casa própria',text:'Um dia de cada vez, vou construindo meu futuro.'},{icon:'📚',title:'Aprender e crescer',text:'Cada estudo é um passo para a vida que quero viver.'},{icon:'🕊️',title:'Meu tempo com Deus',text:'Que minha fé e minha constância floresçam todos os dias.'}];
function slideItems(){return S.slides.length?S.slides:welcomeSlides}
function slideMarkup(){let a=slideItems()[slideIndex%slideItems().length];return `<div class="slide">${a.asset?`<img class="slide-image" alt="Foto do seu mural" data-asset="${esc(a.asset)}">`:''}<div class="slide-content"><span class="caps" style="color:#ffdfed">MEU QUADRO DE INSPIRAÇÕES</span><h2>${esc(a.title||'Meu sonho')} ${a.icon||''}</h2><p>${esc(a.text||'')}</p></div></div><div class="slide-controls">${slideItems().map((_,i)=>`<button aria-label="Mostrar foto ${i+1}" class="slide-dot ${slideIndex===i?'active':''}" data-slide="${i}"></button>`).join('')}</div>`}
function startSlides(){let a=$('#slideHost');if(a)a.innerHTML=slideMarkup();hydrateImages(a||document);if(slideItems().length>1&&!matchMedia('(prefers-reduced-motion: reduce)').matches){slideTimer=setInterval(()=>{if(section!=='inicio')return;slideIndex=(slideIndex+1)%slideItems().length;let el=$('#slideHost');if(el){el.innerHTML=slideMarkup();hydrateImages(el)}},5000)}}
function home(){let st=stats();return `<div class="hero"><div><span class="caps">SEU CANTINHO, SUAS CONQUISTAS</span><h2>Floresça no seu tempo. 🌷</h2><p>Pequenos passos, planos e momentos que fazem parte da sua história.</p><button class="btn" data-nav="rotina">Ver minha rotina →</button></div><div class="hero-icon">🌸</div></div><div class="section-head"><h2>Momentos que me inspiram</h2><button class="btn outline small" data-action="slide-add">+ Adicionar foto</button></div><div id="slideHost"></div><div class="grid3" style="margin-top:22px"><div class="stat"><span>⏳ Tempo registrado hoje</span><b>${formatMin(st.minutes)}</b></div><div class="stat"><span>✅ Registros de hoje</span><b>${st.logs}</b></div><div class="stat"><span>📚 Livros em leitura</span><b>${st.books}</b></div></div><div class="section-head"><h2>Acesso rápido</h2></div><div class="grid3">${[['📖','Ler a Bíblia','Abrir um capítulo quando quiser','biblia'],['📅','Minha rotina','Registrar estudo ou exercício','rotina'],['📚','Minha biblioteca','Continuar o livro de onde parei','biblioteca'],['🌸','Mural dos sonhos','Fotos e planos para seu futuro','mural'],['📝','Meu caderno','Guardar ideias, estudos e memórias','caderno'],['🕊️','Plano bíblico','Acompanhar sua leitura do dia','plano']].map(([e,t,d,id])=>`<button class="card" data-nav="${id}" style="text-align:left;border-color:#f0e0e6"><div style="font-size:31px">${e}</div><b style="display:block;margin:8px 0 2px">${t}</b><span class="muted tiny">${d}</span></button>`).join('')}</div>${S.slides.length?`<div class="toolbar"><button class="btn light small" data-action="slides-manage">Gerenciar fotos da apresentação</button></div>`:''}`}
function profile(){return `<div class="card" style="padding:16px 16px 25px"><div class="profile-banner">${S.profile.cover?`<img data-asset="${esc(S.profile.cover)}" alt="Capa do perfil">`:''}</div><div class="profile-lower"><div class="profile-pic">${S.profile.avatar?`<img style="width:100%;height:100%;object-fit:cover;border-radius:50%" data-asset="${esc(S.profile.avatar)}" alt="Minha foto">`:esc((S.profile.name||'J')[0].toUpperCase())}</div><div><h2 style="margin:22px 0 0;font-family:Georgia,serif">${esc(S.profile.name||'Meu perfil')}</h2><p class="muted tiny" style="margin:4px 0">Meu espaço de crescimento e sonhos ✨</p></div></div><div class="toolbar" style="margin:20px 0 0"><button class="btn" data-action="profile-edit">Editar meu perfil</button></div></div><div class="section-head"><h2>Minha frase</h2></div><div class="profile-quote">“${esc(S.profile.quote||'Não existe mudança sem constância. 🌷')}”</div><div class="section-head"><h2>Minha jornada</h2></div><div class="grid3"><div class="stat"><span>Rotinas cadastradas</span><b>${S.routines.length}</b></div><div class="stat"><span>Registros realizados</span><b>${S.logs.length}</b></div><div class="stat"><span>Livros na estante</span><b>${S.books.length}</b></div></div>`}
function routines(){let st=stats();return `<div class="hero"><div><span class="caps">SEU DIA, SUAS ESCOLHAS</span><h2>Minha rotina ✨</h2><p>Estude, caminhe, trabalhe, ore: acompanhe tudo sem se prender a um limite fixo de tempo. Fotos são opcionais.</p><button class="btn" data-action="routine-new">+ Nova atividade</button></div><div class="hero-icon">🗓️</div></div><div class="grid3" style="margin-top:18px"><div class="stat"><span>Tempo realizado hoje</span><b>${formatMin(st.minutes)}</b></div><div class="stat"><span>Atividades registradas hoje</span><b>${st.logs}</b></div><div class="stat"><span>Atividades cadastradas</span><b>${S.routines.length}</b></div></div><div class="section-head"><h2>Minhas atividades</h2><button class="btn outline small" data-action="routine-new">+ Adicionar</button></div><div class="grid">${S.routines.length?S.routines.map(r=>{let pct=dayPct(r);return `<article class="card routine-card"><div class="routine-top"><div class="symbol">${ICONS[r.category]||'🌷'}</div><div style="flex:1"><span class="caps">${esc(r.category)}</span><h3>${esc(r.title)}</h3></div><span class="pill">${r.targetMinutes?formatMin(r.targetMinutes)+'/dia':'Livre'}</span></div><p class="subtitle">${esc(r.schedule||'Sem dias fixos')} · ${S.logs.filter(l=>l.routineId===r.id).length} registros</p><div class="between tiny"><span>Hoje: <strong>${formatMin(totalMins(r.id,today()))}</strong></span><strong>${pct}%</strong></div>${progressLine(pct)}<div class="card-actions"><button class="btn small" data-action="log-new" data-id="${r.id}">+ Registrar</button><button class="btn outline small" data-action="routine-view" data-id="${r.id}">Histórico</button><button class="btn outline small" data-action="routine-edit" data-id="${r.id}">Editar</button></div></article>`}).join(''):cardEmpty('📅','Sua rotina começa aqui','Adicione uma atividade, como estudar português ou fazer exercícios.','Criar atividade','routine-new')}</div><div class="note">💡 A porcentagem é calculada pelo tempo de referência de cada dia. Se fizer 90 minutos numa referência de 60, aparecerá 150%. Não é um limite!</div>`}
function routineForm(r){return `<h2 id="dialogTitle">${r?'Editar atividade':'Nova atividade'} 🌷</h2><form id="routineForm"><input type="hidden" name="id" value="${esc(r?.id||'')}"><div class="form-group"><label class="label">Nome da atividade *</label><input class="field" name="title" required maxlength="100" placeholder="Ex.: Estudar português" value="${esc(r?.title||'')}"></div><div class="form-grid"><div class="form-group"><label class="label">Categoria</label><select name="category" class="field">${CATS.map(c=>`<option ${r?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-group"><label class="label">Tempo de referência (minutos)</label><input class="field" type="number" name="targetMinutes" min="0" max="1440" value="${Number(r?.targetMinutes??60)}"><small class="help">Use 60 para 1h. O tempo registrado pode ultrapassar essa referência. Use 0 para acompanhamento sem porcentagem de tempo.</small></div></div><div class="form-group"><label class="label">Frequência</label><select class="field" name="schedule">${['Sem dias fixos','Todos os dias','Dias pares','Dias ímpares','Segunda a sexta','3 vezes por semana','4 vezes por semana','5 vezes por semana'].map(x=>`<option ${r?.schedule===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-grid"><div class="form-group"><label class="label">Começa em (opcional)</label><input class="field" type="date" name="start" value="${esc(r?.start||'')}"></div><div class="form-group"><label class="label">Termina em (opcional)</label><input class="field" type="date" name="end" value="${esc(r?.end||'')}"></div></div><div class="toolbar"><button type="submit" class="btn">Salvar atividade</button>${r?`<button type="button" class="btn danger" data-action="routine-delete" data-id="${r.id}">Excluir</button>`:''}</div></form>`}
function logForm(r){return `<h2 id="dialogTitle">Registrar atividade ✨</h2><p class="muted">${esc(r.title)} — pode incluir uma foto, se quiser.</p><form id="logForm"><input name="routineId" type="hidden" value="${esc(r.id)}"><div class="form-grid"><div class="form-group"><label class="label">Dia do registro</label><input class="field" type="date" name="date" value="${today()}" required></div><div class="form-group"><label class="label">Duração em minutos</label><input class="field" type="number" name="minutes" value="30" min="0" max="1440" required></div></div><div class="form-group"><label class="label">Comentário (opcional)</label><textarea class="field" name="note" placeholder="Ex.: Estudei acentuação, consegui fazer os exercícios!"></textarea></div><div class="form-group"><label class="label">Foto do que você fez (opcional)</label><input class="field file-input" type="file" name="photo" accept="image/*"><small class="help">Fotografe o caderno, uma caminhada ou o computador, por exemplo.</small></div><button class="btn" type="submit">Salvar meu registro</button></form>`}
function logView(r){let list=S.logs.filter(l=>l.routineId===r.id).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));let total=totalMins(r.id);return `<div class="toolbar"><button class="btn outline small" data-nav="rotina">← Minha rotina</button><button class="btn small" data-action="log-new" data-id="${r.id}">+ Registrar atividade</button></div><div class="hero"><div><span class="caps">${esc(r.category)}</span><h2>${esc(r.title)}</h2><p>${list.length} registros · ${formatMin(total)} no total</p></div><div class="hero-icon">${ICONS[r.category]||'📚'}</div></div><div class="section-head"><h2>Registros e fotos</h2></div><div class="card">${list.length?list.map(l=>`<div class="timeline-item"><div class="row" style="flex:1;align-items:start">${l.photo?`<button type="button" style="border:0;background:transparent;padding:0" data-action="photo-open" data-id="${esc(l.photo)}" title="Ampliar foto"><img class="thumb" data-asset="${esc(l.photo)}" alt="Foto da atividade"></button>`:'<div class="symbol">✅</div>'}<div><div class="item-title">${formatMin(l.minutes)} <span class="muted tiny">· ${shortDate(l.date)}</span></div><div class="muted tiny">${esc(l.note||'Atividade registrada')}</div></div></div><button class="btn danger small" data-action="log-delete" data-id="${l.id}">Excluir</button></div>`).join(''):cardEmpty('📸','Sem registros ainda','Adicione sua primeira atividade e, se quiser, uma foto.')}</div><div class="section-head"><h2>Progresso do dia</h2></div><div class="card"><div class="form-grid"><div><label class="label">Escolher dia</label><input class="field" id="routineDay" type="date" value="${esc(selectedDate)}"></div><div><span class="muted tiny">Tempo realizado</span><div class="highlight" style="font-size:30px;font-weight:800">${formatMin(totalMins(r.id,selectedDate))}</div></div></div><div class="between"><strong>Referência: ${formatMin(r.targetMinutes)}</strong><strong>${dayPct(r,selectedDate)}%</strong></div>${progressLine(dayPct(r,selectedDate))}<p class="help">A barra fica cheia em 100%, mas o número pode continuar acima de 100%.</p></div>`}
function progressView(){let mins=S.logs.reduce((a,l)=>a+Number(l.minutes||0),0);let byCat={};for(let r of S.routines){let n=totalMins(r.id);byCat[r.category]=(byCat[r.category]||0)+n}return `<div class="hero"><div><span class="caps">CADA PASSO IMPORTA</span><h2>Seu esforço merece ser visto 🌷</h2><p>Acompanhe seus registros, sem misturar tempo realizado com atividades concluídas.</p></div><div class="hero-icon">📊</div></div><div class="grid3" style="margin-top:19px"><div class="stat"><span>Minutos registrados</span><b>${mins}</b></div><div class="stat"><span>Sessões realizadas</span><b>${S.logs.length}</b></div><div class="stat"><span>Dias do plano bíblico lidos</span><b>${S.bible.read.length}</b></div></div><div class="section-head"><h2>Tempo por categoria</h2></div><div class="card">${Object.keys(byCat).length?Object.entries(byCat).map(([c,n])=>`<div style="margin:14px 0"><div class="between tiny"><strong>${ICONS[c]||'🌷'} ${c}</strong><span>${formatMin(n)}</span></div>${progressLine(mins?Math.round(n/mins*100):0)}</div>`).join(''):cardEmpty('📈','Seu histórico vai aparecer aqui','Basta registrar sua primeira atividade.')}</div><div class="note">O progresso diário fica em <b>Minha rotina → Histórico</b>, e se atualiza no momento em que você registra os minutos.</div>`}
function bookName(slug){return B.find(x=>x[1]===slug)?.[0]||slug}
function bibleBookOptions(current){return B.map(([name,slug])=>`<option value="${slug}" ${current===slug?'selected':''}>${name}</option>`).join('')}
function bibleVersionsOptions(){return VERSIONS.map(([key,label])=>`<option value="${key}" ${S.bible.version===key?'selected':''}>${esc(label)}</option>`).join('')}
function bibleControls(){return `<div class="reader-controls"><select aria-label="Tradução" id="bibleVersion" class="field" style="flex:2" title="Tradução">${bibleVersionsOptions()}</select><select aria-label="Livro" id="bibleBook" class="field book-select">${bibleBookOptions(bibleBook)}</select><input aria-label="Capítulo" class="field" id="bibleChapter" type="number" min="1" max="${B.find(x=>x[1]===bibleBook)?.[2]||150}" value="${bibleChapter}" style="max-width:85px"></div>`}
function bibleView(){return `<div class="hero"><div><span class="caps">UM MOMENTO COM DEUS</span><h2>Leia a Bíblia com calma 📖</h2><p>Escolha livremente uma tradução disponível, um livro e um capítulo. A leitura do plano bíblico também abre aqui.</p></div><div class="hero-icon">🕊️</div></div><div class="section-head"><h2>Leitor da Bíblia</h2><span class="pill">7 traduções livres</span></div><div class="card">${bibleControls()}<div class="between" style="margin-bottom:14px"><button class="btn outline small" data-action="bible-prev">← Anterior</button><strong>${esc(bookName(bibleBook))} ${bibleChapter}</strong><button class="btn light small" data-action="bible-next">Próximo →</button></div><div class="card-actions"><button class="btn light small" data-action="verse-notes-list">✎ Minhas anotações</button></div><div class="bible-text" id="bibleContent"><p class="muted">Carregando texto bíblico…</p></div><div id="bibleCopyright" class="attribution"></div><div class="note" style="margin-top:17px">O texto bíblico usa uma fonte pública de traduções em domínio público ou com licença aberta. Requer conexão com a internet. A NVI, NTLH e outras traduções protegidas não podem ser copiadas integralmente para cá sem licença.</div><a class="btn outline small" target="_blank" rel="noopener noreferrer" href="https://www.bible.com/pt">Consultar outras traduções em plataforma autorizada ↗</a></div>`}
// A API Midvash devolve os versículos como strings, não como objetos.
// Compatibilidade com respostas que tenham versículos em outros formatos.
function parseVerses(payload){
  const data=payload?.data??payload;
  const verses=data?.verses??data?.chapter?.verses??payload?.verses;
  if(Array.isArray(verses)){
    const parsed=verses.map((v,i)=>{
      if(typeof v==='string')return {n:i+1,t:v};
      if(v&&typeof v==='object')return {
        n:v.verse??v.number??i+1,
        t:String(v.text??v.content??v.verseText??v.value??'')
      };
      return {n:i+1,t:''};
    }).filter(v=>v.t.trim().length>0);
    if(parsed.length)return parsed;
  }
  if(typeof data?.text==='string'&&data.text.trim())return [{n:'',t:data.text}];
  if(typeof data==='string'&&data.trim())return [{n:'',t:data}];
  return [];
}
async function loadBibleText(){let el=$('#bibleContent'),copyright=$('#bibleCopyright');if(!el)return;let myBook=bibleBook,myChapter=bibleChapter,myVersion=S.bible.version;el.innerHTML='<p class="muted">Carregando capítulo…</p>';copyright.textContent='';try{const controller=new AbortController();let tm=setTimeout(()=>controller.abort(),17000);let resp=await fetch(`https://api.midvash.com/v1/${encodeURIComponent(myVersion)}/${encodeURIComponent(myBook)}/${myChapter}`,{signal:controller.signal});clearTimeout(tm);if(!resp.ok)throw Error('Capítulo não encontrado nesta tradução.');let payload=await resp.json();if(section!=='biblia'&&section!=='plano')return;if(myBook!==bibleBook||myChapter!==bibleChapter||myVersion!==S.bible.version)return;let verses=parseVerses(payload);if(!verses.length)throw Error('Não foi possível interpretar o texto retornado.');el.innerHTML=verses.map(v=>`<p class="verse">${v.n?`<button type="button" class="verse-note-trigger" data-action="verse-note" data-id="${esc(v.n)}" title="Anotar versículo ${esc(v.n)}"><sup>${esc(v.n)}</sup> ✎</button>`:''}${esc(v.t)}</p>`).join('');copyright.textContent=payload?.meta?.copyright||payload?.copyright||'Créditos conforme licença da tradução.';el.scrollTop=0;let notice=payload?.meta?.versionNotice;if(notice)toast('Tradução solicitada indisponível; confira a versão exibida.');}catch(e){if(el){el.innerHTML=`<div class="empty"><span class="em">📖</span><strong>Não foi possível carregar o capítulo.</strong><p>${esc(e.message)} Confira sua conexão e tente novamente.</p><button class="btn light small" data-action="bible-retry">Tentar novamente</button></div>`}}}
function setChapter(slug,chapter){let item=B.find(x=>x[1]===slug);if(!item)return;let c=Math.max(1,Math.min(item[2],Math.round(Number(chapter)||1)));bibleBook=slug;bibleChapter=c;S.bible.book=slug;S.bible.chapter=c;persist();if(section==='biblia')render();else{let t=$('#bibleContent');if(t)loadBibleText()}}
function nextBible(delta){let i=B.findIndex(x=>x[1]===bibleBook);if(i<0)return;let n=bibleChapter+delta;if(n>B[i][2]){i=(i+1)%B.length;n=1}else if(n<1){i=(i-1+B.length)%B.length;n=B[i][2]}setChapter(B[i][1],n)}
// Sugestão anual gerada automaticamente, editável por dia.
const chapters=B.flatMap(x=>Array.from({length:x[2]},(_,j)=>({book:x[1],chapter:j+1})));
function suggestedDay(date){let d=new Date(`${date}T12:00:00`);if(!Number.isFinite(d.getTime()))return null;let year=d.getFullYear(),start=new Date(year,0,1,12);let ordinal=Math.round((d-start)/86400000),yearLen=new Date(year,1,29).getMonth()===1?366:365;let i=Math.floor(ordinal*chapters.length/yearLen),k=Math.floor((ordinal+1)*chapters.length/yearLen)-1;i=Math.min(chapters.length-1,Math.max(0,i));k=Math.min(chapters.length-1,Math.max(i,k));return {book:chapters[i].book,from:chapters[i].chapter,to:chapters[k].book===chapters[i].book?chapters[k].chapter:chapters[i].chapter,other:chapters[k].book!==chapters[i].book?`${bookName(chapters[k].book)} ${chapters[k].chapter}`:''}}
function getPlan(date){return S.bible.plan[date]||suggestedDay(date)}
function planLabel(p){return p?`${bookName(p.book)} ${p.from}${p.to>p.from?` e ${p.to}`:''}${p.other?` + ${p.other}`:''}`:'Sem leitura'}
function verseNoteKey(verse){return `${bibleBook}:${bibleChapter}:${verse}`}
function openVerseNote(verse){const k=verseNoteKey(verse),old=S.bible.verseNotes?.[k]||'';openDialog(`<h2 id="dialogTitle">Minha anotação · ${esc(bookName(bibleBook))} ${bibleChapter}:${esc(verse)}</h2><form id="verseNoteForm"><input type="hidden" name="key" value="${esc(k)}"><label class="label">O que entendi deste versículo?</label><textarea class="field" name="text" rows="7" placeholder="Escreva aqui sua reflexão...">${esc(old)}</textarea><div class="card-actions"><button class="btn" type="submit">Salvar anotação</button><button class="btn outline" type="button" data-action="verse-notes-list">Minhas anotações</button></div></form>`)}
function openVerseNotesList(){let entries=Object.entries(S.bible.verseNotes||{});openDialog(`<h2 id="dialogTitle">Minhas anotações bíblicas 📖</h2>${entries.length?entries.map(([key,txt])=>`<div class="timeline-item"><div><strong>${esc(key.replace(/:/g,' · '))}</strong><p>${esc(txt)}</p></div><button class="btn danger small" data-action="verse-note-delete" data-id="${esc(key)}">Excluir</button></div>`).join(''):'<p class="muted">Você ainda não fez anotações.</p>'}`)}
function planView(){let p=getPlan(chosenBibleDay),isRead=S.bible.read.includes(chosenBibleDay),month=chosenBibleDay.slice(0,7),[y,m]=month.split('-').map(Number),first=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),padding=first.getDay(),cal=Array.from({length:padding},()=>'<span></span>').join('')+Array.from({length:days},(_,i)=>{let date=`${y}-${String(m).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<button type="button" data-plan-day="${date}" class="cal-day ${date===today()?'today':''} ${S.bible.read.includes(date)?'read':''} ${date===chosenBibleDay?'selected':''}">${i+1}${date===today()?'<span class="dot"></span>':''}</button>`}).join('');return `<div class="hero"><div><span class="caps">LEITURA DIÁRIA</span><h2>Meu plano bíblico 🕊️</h2><p>Toque na leitura do dia para abrir o primeiro capítulo. Depois avance para o próximo e marque como lido.</p></div><div class="hero-icon">📖</div></div><div class="grid" style="margin-top:18px;align-items:start"><div class="card"><div class="between"><button class="btn outline small" data-action="month-prev">←</button><strong>${first.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button class="btn outline small" data-action="month-next">→</button></div><div class="calendar" style="margin-top:10px">${['D','S','T','Q','Q','S','S'].map(d=>`<div class="weekday">${d}</div>`).join('')}${cal}</div><div class="note">🌸 Rosa: dia de hoje · Verde: leitura concluída. Você pode mudar a leitura de qualquer data.</div></div><div class="card"><div class="between"><span class="caps">${chosenBibleDay===today()?'✨ LEITURA DE HOJE':'LEITURA SELECIONADA'}</span><span class="pill">${shortDate(chosenBibleDay)}</span></div><h2 class="chapter-title">${esc(planLabel(p))}</h2><p class="muted tiny">${S.bible.plan[chosenBibleDay]?'Leitura personalizada':'Sugestão do plano anual (editável)'}</p><div class="card-actions"><button class="btn" data-action="plan-open">📖 Abrir leitura</button><button class="btn outline small" data-action="plan-edit">Editar capítulos</button></div><label class="checkrow" style="margin-top:20px"><input type="checkbox" id="planDone" ${isRead?'checked':''}> Marcar esta leitura como concluída</label><div class="divider"></div><div class="between tiny"><strong>${S.bible.read.filter(d=>d.startsWith(chosenBibleDay.slice(0,4))).length} dias concluídos no ano</strong><button class="btn light small" data-action="plan-today">Ir para hoje</button></div></div></div>${planFlow?`<div class="section-head"><h2>Leitura aberta</h2></div><div class="card"><div class="between"><strong>${esc(bookName(bibleBook))} ${bibleChapter}</strong><span class="pill">${bibleChapter-planFlow.from+1} de ${planFlow.to-planFlow.from+1}</span></div><div class="reader-controls" style="margin-top:13px"><select class="field" id="bibleVersion">${bibleVersionsOptions()}</select><button class="btn light" data-action="plan-next">${bibleChapter>=planFlow.to?'Concluir leitura ✓':'Próximo capítulo →'}</button></div><div class="card-actions"><button class="btn light small" data-action="verse-notes-list">✎ Minhas anotações</button></div><div class="bible-text" id="bibleContent"><span class="muted">Carregando…</span></div><div class="attribution" id="bibleCopyright"></div></div>`:''}<div class="note">O plano anual automático é uma <b>sugestão</b>, não uma cópia do seu plano anterior. A leitura Atos 15 e 16 em 23/11/2026 já está registrada conforme seu exemplo, e você pode personalizar qualquer outra data.</div>`}
function planEdit(){let p=getPlan(chosenBibleDay);return `<h2 id="dialogTitle">Leitura de ${shortDate(chosenBibleDay)} 📖</h2><form id="planForm"><div class="form-group"><label class="label">Livro</label><select class="field" name="book">${bibleBookOptions(p.book)}</select></div><div class="form-grid"><div class="form-group"><label class="label">Do capítulo</label><input class="field" type="number" name="from" min="1" value="${p.from}" required></div><div class="form-group"><label class="label">Até o capítulo</label><input class="field" type="number" name="to" min="1" value="${p.to}" required></div></div><p class="help">Ex.: para Atos 15 e 16, escolha Atos / do 15 até o 16.</p><button type="submit" class="btn">Salvar leitura</button></form>`}
function notebook(){let notes=[...S.notes].sort((a,b)=>b.updated.localeCompare(a.updated));return `<div class="hero"><div><span class="caps">PALAVRAS E IDEIAS</span><h2>Meu caderno de anotações 📝</h2><p>Um lugar só seu para guardar qualquer assunto: estudos, pensamentos, planos e lembretes.</p><button class="btn" data-action="note-new">+ Nova anotação</button></div><div class="hero-icon">📓</div></div><div class="section-head"><h2>Minhas anotações</h2></div><div class="grid">${notes.length?notes.map(n=>`<article class="card"><span class="caps">${shortDate(n.updated.slice(0,10))}</span><h3 style="margin:9px 0">${esc(n.title)}</h3><p class="muted tiny">${esc(n.text.slice(0,160))}${n.text.length>160?'…':''}</p><div class="card-actions"><button class="btn light small" data-action="note-edit" data-id="${n.id}">Abrir e editar</button><button class="btn danger small" data-action="note-delete" data-id="${n.id}">Excluir</button></div></article>`).join(''):cardEmpty('📝','Seu caderno está esperando','Escreva sua primeira anotação.','Escrever','note-new')}</div>`}
function noteForm(n){return `<h2 id="dialogTitle">${n?'Editar anotação':'Nova anotação'} 📝</h2><form id="noteForm"><input name="id" type="hidden" value="${esc(n?.id||'')}"><div class="form-group"><label class="label">Título</label><input class="field" name="title" required maxlength="120" value="${esc(n?.title||'')}"></div><div class="form-group"><label class="label">Seu texto</label><textarea class="field" style="min-height:240px" name="text" required>${esc(n?.text||'')}</textarea></div><button class="btn" type="submit">Salvar anotação</button></form>`}
function dreams(){return `<div class="hero"><div><span class="caps">SONHOS QUE ME MOVEM</span><h2>Meu mural dos sonhos 🌸</h2><p>Casa própria, trabalho, viagens e tudo o que você deseja conquistar.</p><button class="btn" data-action="dream-new">+ Adicionar sonho</button></div><div class="hero-icon">🏡</div></div><div class="section-head"><h2>Meu mural</h2></div><div class="grid3">${S.dreams.length?S.dreams.map(d=>`<article class="card dream-card"><div class="cover">${d.photo?`<img data-asset="${esc(d.photo)}" alt="Foto do sonho" style="width:100%;height:100%;object-fit:cover">`:'✨'}</div><h3>${esc(d.title)}</h3><p class="muted tiny">${esc(d.text||'Um sonho que estou construindo.')}</p><div class="card-actions"><button class="btn light small" data-action="dream-edit" data-id="${d.id}">Editar</button><button class="btn danger small" data-action="dream-delete" data-id="${d.id}">Excluir</button></div></article>`).join(''):cardEmpty('🌷','Seu mural começa com um sonho','Adicione a foto de sua futura casa, seu novo trabalho ou outro sonho.','Adicionar sonho','dream-new')}</div>`}
function dreamForm(d){return `<h2 id="dialogTitle">${d?'Editar sonho':'Adicionar um sonho'} 🌷</h2><form id="dreamForm"><input type="hidden" name="id" value="${esc(d?.id||'')}"><div class="form-group"><label class="label">Meu sonho</label><input class="field" name="title" required maxlength="100" value="${esc(d?.title||'')}"></div><div class="form-group"><label class="label">Descrição (opcional)</label><textarea class="field" name="text">${esc(d?.text||'')}</textarea></div><div class="form-group"><label class="label">Fotografia (opcional)</label><input class="field file-input" name="photo" type="file" accept="image/*"></div><button class="btn" type="submit">Salvar no mural</button></form>`}
let bookSearchResults=[];
async function searchCatalog(){let input=document.getElementById('catalogQuery'),host=document.getElementById('catalogResults');if(!input||!host)return;let q=input.value.trim();if(!q)return;host.textContent='Pesquisando livros…';try{let r=await fetch('https://openlibrary.org/search.json?q='+encodeURIComponent(q)+'&limit=8');if(!r.ok)throw Error('Serviço indisponível');let d=await r.json();bookSearchResults=(d.docs||[]).map(x=>({title:x.title||'',author:(x.author_name||[])[0]||'',cover:x.cover_i?`https://covers.openlibrary.org/b/id/${x.cover_i}-M.jpg`:''}));host.innerHTML=bookSearchResults.map((b,i)=>`<div class="timeline-item"><div class="row">${b.cover?`<img src="${esc(b.cover)}" alt="Capa" style="width:48px;height:70px;object-fit:contain">`:''}<div><strong>${esc(b.title)}</strong><p class="muted tiny">${esc(b.author)}</p></div></div><button class="btn small" data-action="catalog-add" data-id="${i}">Adicionar à estante</button></div>`).join('')||'<p>Nenhum livro encontrado.</p>'}catch(e){host.textContent='Não foi possível pesquisar. Verifique a conexão e tente novamente.'}}
function library(){return `<div class="hero"><div><span class="caps">UM LIVRO DE CADA VEZ</span><h2>Minha biblioteca 📚</h2><p>Adicione arquivos PDF ou EPUB que você pode usar legalmente. Continue de onde parou, sem procurar a página novamente.</p><button class="btn" data-action="book-new">+ Adicionar livro</button></div><div class="hero-icon">📖</div></div><div class="card" style="margin-top:16px"><h3>Pesquisar livros por título ou autor</h3><div class="reader-controls"><input class="field" id="catalogQuery" placeholder="Digite o nome do livro"><button class="btn" data-action="catalog-search">Pesquisar</button></div><div id="catalogResults"></div><p class="muted tiny">A pesquisa adiciona os dados à estante; a leitura integral depende de uma edição legalmente disponível.</p></div><div class="section-head"><h2>Minha estante</h2><span class="muted tiny">${S.books.length} livro(s)</span></div><div class="book-covers">${S.books.length?S.books.map(b=>`<article class="card book-card" style="padding:13px"><div class="book-cover">${(b.cover||b.coverUrl)?(b.cover?`<img data-asset="${esc(b.cover)}" alt="Capa do livro">`:`<img src="${esc(b.coverUrl)}" alt="Capa do livro">`):'📚'}</div><h3>${esc(b.title)}</h3><div class="muted tiny">${esc(b.author||'Autor não informado')} · ${esc(b.kind.toUpperCase())}</div><p class="tiny">${b.kind==='pdf'?`Página ${b.page||1}${b.pages?' de '+b.pages:''}`:b.percent?`${Math.round(b.percent)}% lido`:'Aguardando leitura'} · <span class="pill">${esc(b.status||'quero ler')}</span></p><div class="card-actions"><button class="btn small" data-action="${b.kind==='catalog'?'book-edit':'book-open'}" data-id="${b.id}">${b.kind==='catalog'?'Detalhes':'📖 Continuar'}</button><button class="btn outline small" data-action="book-edit" data-id="${b.id}">Editar</button></div></article>`).join(''):cardEmpty('📚','Sua estante está vazia','Adicione um PDF ou EPUB para começar a ler.','Adicionar livro','book-new')}</div><div class="note">📘 O site guarda a página de PDFs e a posição de EPUBs neste navegador. Para acessar de outros aparelhos, será necessária a sincronização na nuvem; enquanto isso, use o backup.</div>`}
function bookForm(b){return `<h2 id="dialogTitle">${b?'Editar livro':'Adicionar livro'} 📚</h2><form id="bookForm"><input type="hidden" name="id" value="${esc(b?.id||'')}"><div class="form-group"><label class="label">Título</label><input name="title" maxlength="150" class="field" value="${esc(b?.title||'')}"></div><div class="form-group"><label class="label">Autor</label><input name="author" maxlength="150" class="field" value="${esc(b?.author||'')}"></div>${b?'':`<div class="form-group"><label class="label">Arquivo PDF ou EPUB *</label><input class="field file-input" type="file" name="file" accept=".pdf,.epub,application/pdf,application/epub+zip" required></div>`}<div class="form-group"><label class="label">Capa (opcional)</label><input class="field file-input" type="file" name="cover" accept="image/*"></div><div class="form-group"><label class="label">Status</label><select class="field" name="status">${['quero ler','lendo','concluído'].map(x=>`<option ${b?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="toolbar"><button class="btn" type="submit">Salvar livro</button>${b?`<button type="button" class="btn danger" data-action="book-delete" data-id="${b.id}">Excluir livro</button>`:''}</div></form><p class="fine-print">Não envie livros protegidos por direitos autorais sem autorização para redistribuição. Seus arquivos ficam apenas no armazenamento do seu navegador, não no repositório público.</p>`}
async function readBook(id){let b=S.books.find(x=>x.id===id);if(!b)return;let a=await getAsset(b.asset);if(!a?.blob){toast('O arquivo não foi encontrado neste aparelho. Restaure um backup.');return}activeBook=b.id;b.status='lendo';persist();openDialog(`<h2 id="dialogTitle">${esc(b.title)}</h2><p class="muted tiny" id="readerInfo">Abrindo sua leitura…</p><div class="toolbar"><button class="btn light small" data-action="reader-prev">← Página anterior</button><button class="btn light small" data-action="reader-next">Próxima página →</button><button class="btn outline small" data-action="reader-close">Fechar e salvar</button></div><div id="readerBody" class="${b.kind==='pdf'?'pdf-area':'epub-area'}"></div><div class="form-group" style="margin-top:12px" id="readerJump">${b.kind==='pdf'?`<label class="label">Ir para página</label><input class="field" style="max-width:130px" type="number" id="readerPage" min="1" value="${b.page||1}">`:''}</div>`);await hydrateImages($('#dialog'));if(b.kind==='pdf')await openPdf(b,a.blob);else await openEpub(b,a.blob)}
function loadScript(url,test){return new Promise((resolve,reject)=>{if(test())return resolve();let s=document.createElement('script');s.src=url;s.onload=()=>resolve();s.onerror=()=>reject(Error('Biblioteca de leitura indisponível. Verifique a internet.'));document.head.append(s)})}
async function openPdf(b,blob){try{await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js',()=>!!window.pdfjsLib);pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';let buf=await blob.arrayBuffer();currentPdfDoc=await pdfjsLib.getDocument({data:buf}).promise;b.pages=currentPdfDoc.numPages;b.page=Math.max(1,Math.min(b.pages,Number(b.page)||1));await persist();await paintPdf(b)}catch(err){let div=$('#readerBody');if(div){let url=URL.createObjectURL(blob);imageUrls.push(url);div.innerHTML=`<p class="danger-note">${esc(err.message)} Você ainda pode abrir o PDF abaixo, mas o avanço automático por página pode ficar indisponível.</p><iframe title="Livro PDF" src="${url}" style="width:100%;height:60vh;border:0"></iframe>`}}}
async function paintPdf(b){if(!currentPdfDoc||!$('#readerBody'))return;let pg=await currentPdfDoc.getPage(b.page);let viewport=pg.getViewport({scale:1.3});let canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;await pg.render({canvasContext:canvas.getContext('2d'),viewport}).promise;let div=$('#readerBody');if(!div)return;div.replaceChildren(canvas);let info=$('#readerInfo');if(info)info.textContent=`Página ${b.page} de ${b.pages} · posição salva automaticamente`;let inp=$('#readerPage');if(inp)inp.value=b.page;persist()}
async function openEpub(b,blob){try{await loadScript('https://cdn.jsdelivr.net/npm/epubjs@0.3.93/dist/epub.min.js',()=>!!window.ePub);let buf=await blob.arrayBuffer();ebookObj=window.ePub(buf);ebookObj.ready.then(()=>ebookObj.locations.generate(1200)).catch(()=>{});currentRendition=ebookObj.renderTo($('#readerBody'),{width:'100%',height:'100%',spread:'none'});currentRendition.on('relocated',loc=>{if(!activeBook||activeBook!==b.id)return;b.cfi=loc.start.cfi;b.percent=ebookObj?.locations?.length?.()?Math.round(ebookObj.locations.percentageFromCfi(loc.start.cfi)*100):(loc.start.percentage?Math.round(loc.start.percentage*100):b.percent||0);let info=$('#readerInfo');if(info)info.textContent=`${b.percent||0}% lido · posição salva automaticamente`;persist()});await currentRendition.display(b.cfi||undefined)}catch(e){let div=$('#readerBody');if(div)div.innerHTML=`<div class="danger-note">Não foi possível abrir este EPUB: ${esc(e.message)}. Verifique se o arquivo é válido e sua internet está funcionando.</div>`}}
async function readerMove(n){let b=S.books.find(x=>x.id===activeBook);if(!b)return;if(b.kind==='pdf'){if(!currentPdfDoc)return;b.page=Math.max(1,Math.min(b.pages,b.page+n));await paintPdf(b)}else if(currentRendition){await (n>0?currentRendition.next():currentRendition.prev())}}
function settings(){return `<div class="hero"><div><span class="caps">SUAS INFORMAÇÕES IMPORTAM</span><h2>Ajustes e backups ⚙️</h2><p>Guarde uma cópia dos seus dados antes de trocar de celular, limpar o navegador ou atualizar o site.</p></div><div class="hero-icon">🔐</div></div><div class="section-head"><h2>Salvar e recuperar</h2></div><div class="card stack"><div><h3>⬇ Baixar backup completo</h3><p class="muted tiny">Inclui suas rotinas, anotações, progresso, fotos e livros. Como pode ficar grande, guarde numa pasta privada.</p><button class="btn" data-action="export">Baixar meu backup</button></div><hr class="divider"><div><h3>⬆ Restaurar um backup</h3><p class="muted tiny">Aceita backups desta versão e o arquivo JSON exportado da versão anterior do Meus Sonhos & Metas.</p><input class="field file-input" type="file" id="importBackup" accept=".json,application/json"><button class="btn light" style="margin-top:10px" data-action="import-backup">Importar dados</button></div><div class="danger-note"><b>Privacidade:</b> nesta versão de testes, os arquivos ficam no navegador deste aparelho. O endereço do site pode ser visitado por outras pessoas e os dados não estão protegidos por login. Não coloque fotos nem livros pessoais dentro do repositório público do GitHub. O backup JSON não é criptografado.</div></div><div class="section-head"><h2>Sobre a sincronização</h2></div><div class="card"><p>O GitHub Pages hospeda o visual do site, mas não armazena seus registros particulares. Para ter fotos, livros e anotações sincronizados entre iPhone e computador com acesso privado, a próxima etapa é configurar um serviço como Firebase ou Supabase com login e regras de acesso.</p><p class="muted tiny">A futura integração não está ativa nesta versão. Não podemos prometer sincronização automática até ela estar configurada e testada.</p></div>${S.legacy?`<div class="note">✅ Foi preservada uma cópia dos dados originais importados do aplicativo anterior, inclusive campos que não aparecem nesta versão. Ela será incluída no próximo backup.</div>`:''}`}
function profileForm(){return `<h2 id="dialogTitle">Personalizar meu perfil 🌷</h2><form id="profileForm"><div class="form-group"><label class="label">Seu nome</label><input class="field" name="name" value="${esc(S.profile.name)}" maxlength="65"></div><div class="form-group"><label class="label">Sua frase</label><textarea class="field" name="quote" maxlength="220">${esc(S.profile.quote)}</textarea></div><div class="form-group"><label class="label">Foto de perfil (opcional)</label><input class="field file-input" type="file" name="avatar" accept="image/*"></div><div class="form-group"><label class="label">Foto de capa (opcional)</label><input class="field file-input" type="file" name="cover" accept="image/*"></div><button class="btn" type="submit">Salvar meu perfil</button></form>`}
function slideForm(){return `<h2 id="dialogTitle">Foto da tela inicial 🌸</h2><form id="slideForm"><div class="form-group"><label class="label">Título</label><input class="field" name="title" required maxlength="90" placeholder="Ex.: Minha casa própria"></div><div class="form-group"><label class="label">Frase</label><textarea class="field" name="text" maxlength="210" placeholder="Cada dia mais perto desse sonho"></textarea></div><div class="form-group"><label class="label">Fotografia (opcional)</label><input class="field file-input" type="file" name="photo" accept="image/*"></div><button type="submit" class="btn">Adicionar à apresentação</button></form>`}
function openDialog(content){$('#dialogBody').innerHTML=content;$('#dialog').hidden=false;document.body.style.overflow='hidden';setTimeout(()=>$('#dialog .field')?.focus(),10)}
function closeDialog(){if(currentRendition){try{currentRendition.destroy()}catch{}}currentRendition=null;ebookObj=null;currentPdfDoc=null;activeBook=null;$('#dialog').hidden=true;document.body.style.overflow='';render()}
function inputValue(form,name){return String(new FormData(form).get(name)||'').trim()}
async function photoField(form,key){let f=form.elements.namedItem(key)?.files?.[0];if(!f)return null;if(!f.type.startsWith('image/'))throw Error('Escolha uma imagem válida.');if(f.size>12*1024*1024)throw Error('Imagem acima de 12 MB; escolha uma imagem menor.');return storeAsset(f)}
async function fileToDataUrl(blob){return new Promise((res,rej)=>{let fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=()=>rej(fr.error);fr.readAsDataURL(blob)})}
function dataUrlToBlob(url){let [head,base]=url.split(',');let mime=/data:(.*?);base64/.exec(head)?.[1]||'application/octet-stream';let bytes=atob(base),n=bytes.length,arr=new Uint8Array(n);for(let i=0;i<n;i++)arr[i]=bytes.charCodeAt(i);return new Blob([arr],{type:mime})}
async function exportBackup(){toast('Preparando cópia dos dados e arquivos…');let out={app:'Meus Sonhos & Metas (v2)',format:'v2',exportedAt:new Date().toISOString(),state:S,assets:{}};let keys=await reqPromise(tx('assets').getAllKeys());for(let id of keys){let a=await getAsset(id);if(a?.blob)out.assets[id]={data:await fileToDataUrl(a.blob),name:a.name,type:a.type}}let blob=new Blob([JSON.stringify(out)],{type:'application/json'});let url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=`meus-sonhos-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Backup baixado! Guarde o arquivo em local privado.')}
function oldToNew(raw){let s=defaultState();s.legacy=raw;if(raw.profile){s.profile.name=raw.profile.displayName||'';s.profile.quote=raw.profile.bio||s.profile.quote}for(let g of raw.goals||[]){let id=String(g.id||uid());let title=String(g.title||'Atividade').trim();let target=Number((String(g.notes||'').match(/(\d+)\s*(?:hora|h)\s*(?:por dia|diariament|todo dia)?/i)||[])[1]);let r={id,title,category:CATS.includes(g.category)?g.category:'Outros',targetMinutes:target?target*60:60,schedule:g.schedule?.mode==='daily'?'Todos os dias':g.schedule?.mode==='even'?'Dias pares':g.schedule?.mode==='odd'?'Dias ímpares':'Sem dias fixos',start:g.schedule?.start||'',end:g.schedule?.end||''};s.routines.push(r);for(let t of g.studySessions||[]){if(!/^\d{4}-\d{2}-\d{2}$/.test(t.date))continue;s.logs.push({id:String(t.id||uid()),routineId:id,date:t.date,minutes:Math.round(Number(t.seconds||0)/60),note:'Importado do histórico anterior',photo:null})}for(let d of g.doneDates||[]){if(typeof d==='string'&&!s.logs.some(l=>l.routineId===id&&l.date===d))s.logs.push({id:uid(),routineId:id,date:d,minutes:0,note:'Dia concluído no aplicativo anterior',photo:null})}}
for(let t of raw.routines||[]){if(!t.title)continue;let id=String(t.id||uid());if(!s.routines.some(r=>r.id===id))s.routines.push({id,title:String(t.title),category:'Pessoal',targetMinutes:0,schedule:'Sem dias fixos',start:'',end:''});for(let d of t.doneDates||[]){if(typeof d==='string')s.logs.push({id:uid(),routineId:id,date:d,minutes:0,note:'Registro de rotina importado',photo:null})}}
return s}
async function importBackup(file){if(!file)throw Error('Escolha um arquivo JSON.');if(file.size>250*1024*1024)throw Error('O arquivo é muito grande.');let raw=JSON.parse(await file.text());let newer=raw.format==='v2'&&raw.state&&raw.assets;let older=Array.isArray(raw.goals);if(!newer&&!older)throw Error('Formato de backup não reconhecido.');if(!confirm('A importação substituirá os dados desta versão de testes neste aparelho. Antes, você fez um backup dos dados daqui?'))return;toast('Importando dados. Aguarde…');if(newer){let entries=Object.entries(raw.assets||{});for(let [id,a] of entries){let blob=dataUrlToBlob(a.data);await reqPromise(tx('assets','readwrite').put({blob,name:a.name,type:a.type},id))}S={...defaultState(),...raw.state};}else{S=oldToNew(raw);if(raw.profile?.photo?.startsWith('data:image/')){S.profile.avatar=await storeAsset(dataUrlToBlob(raw.profile.photo))}}await persist();go('inicio');toast('Importação concluída. Confira seus registros!')}
async function actionDo(name,id,el){try{switch(name){
case 'close-dialog':closeDialog();break;
case 'profile-edit':openDialog(profileForm());break;
case 'routine-new':openDialog(routineForm());break;
case 'routine-edit':openDialog(routineForm(S.routines.find(r=>r.id===id)));break;
case 'routine-view':selectedRoutine=id;selectedDate=today();section='rotina';$('#view').innerHTML=logView(S.routines.find(r=>r.id===id));hydrateImages($('#view'));break;
case 'routine-delete':if(confirm('Excluir esta atividade e seu histórico?')){S.routines=S.routines.filter(r=>r.id!==id);S.logs=S.logs.filter(l=>l.routineId!==id);await persist();closeDialog();toast('Atividade excluída.')}break;
case 'log-new':{let r=S.routines.find(r=>r.id===id);if(r)openDialog(logForm(r))}break;
case 'log-delete':if(confirm('Excluir este registro de atividade?')){S.logs=S.logs.filter(l=>l.id!==id);await persist();$('#view').innerHTML=logView(S.routines.find(r=>r.id===selectedRoutine));hydrateImages($('#view'));toast('Registro excluído.')}break;
case 'note-new':openDialog(noteForm());break;
case 'note-edit':openDialog(noteForm(S.notes.find(n=>n.id===id)));break;
case 'note-delete':if(confirm('Excluir esta anotação?')){S.notes=S.notes.filter(n=>n.id!==id);await persist();render()}break;
case 'dream-new':openDialog(dreamForm());break;
case 'dream-edit':openDialog(dreamForm(S.dreams.find(d=>d.id===id)));break;
case 'dream-delete':if(confirm('Excluir este sonho?')){S.dreams=S.dreams.filter(d=>d.id!==id);await persist();render()}break;
case 'photo-open':openDialog(`<h2 id="dialogTitle">Foto do meu registro 📸</h2><img data-asset="${esc(id)}" alt="Foto do meu registro" style="display:block;width:100%;max-height:68vh;object-fit:contain;border-radius:14px">`);await hydrateImages($('#dialog'));break;
case 'slide-add':openDialog(slideForm());break;
case 'slides-manage':openDialog(`<h2 id="dialogTitle">Minhas fotos da tela inicial</h2>${S.slides.map(s=>`<div class="timeline-item"><b>${esc(s.title)}</b><button class="btn danger small" data-action="slide-delete" data-id="${s.id}">Excluir</button></div>`).join('')}<div class="toolbar"><button class="btn" data-action="slide-add">+ Nova foto</button></div>`);break;
case 'slide-delete':if(confirm('Remover esta foto da apresentação?')){S.slides=S.slides.filter(x=>x.id!==id);slideIndex=0;await persist();closeDialog()}break;
case 'bible-prev':nextBible(-1);break;
case 'bible-next':nextBible(1);break;
case 'bible-retry':loadBibleText();break;
case 'verse-note':openVerseNote(id);break;
case 'verse-notes-list':openVerseNotesList();break;
case 'verse-note-delete':if(confirm('Excluir esta anotação?')){delete S.bible.verseNotes[id];await persist();openVerseNotesList()}break;
case 'month-prev':changeMonth(-1);break;
case 'month-next':changeMonth(1);break;
case 'plan-today':chosenBibleDay=today();planFlow=null;render();break;
case 'plan-edit':openDialog(planEdit());break;
case 'plan-open':{let p=getPlan(chosenBibleDay);if(!p)return;planFlow={book:p.book,from:p.from,to:p.to,date:chosenBibleDay};bibleBook=p.book;bibleChapter=p.from;render()}break;
case 'plan-next':if(!planFlow)return;if(bibleChapter<planFlow.to){bibleChapter++;render()}else{if(!S.bible.read.includes(planFlow.date))S.bible.read.push(planFlow.date);await persist();planFlow=null;render();toast('Leitura concluída! 🙏')}break;
case 'catalog-search':await searchCatalog();break;
case 'catalog-add':{let b=bookSearchResults[Number(id)];if(!b)break;if(S.books.some(x=>x.title===b.title&&x.author===b.author)){toast('Livro já está na estante.');break}S.books.push({id:uid(),title:b.title,author:b.author,kind:'catalog',coverUrl:b.cover,cover:null,status:'quero ler',page:1,percent:0});await persist();render();toast('Livro adicionado à estante!')}break;
case 'book-new':openDialog(bookForm());break;
case 'book-edit':openDialog(bookForm(S.books.find(b=>b.id===id)));break;
case 'book-delete':if(confirm('Excluir este livro da estante?')){S.books=S.books.filter(b=>b.id!==id);await persist();closeDialog()}break;
case 'book-open':await readBook(id);break;
case 'reader-next':await readerMove(1);break;
case 'reader-prev':await readerMove(-1);break;
case 'reader-close':closeDialog();break;
case 'export':await exportBackup();break;
case 'import-backup':await importBackup($('#importBackup')?.files?.[0]);break;
}}catch(e){console.error(e);toast('Não foi possível concluir: '+e.message)}}
function changeMonth(n){let [y,m]=chosenBibleDay.slice(0,7).split('-').map(Number);let d=new Date(y,m-1+n,1,12);chosenBibleDay=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;planFlow=null;render()}
async function handleForm(form){try{const type=form.getAttribute('id');if(type==='profileForm'){S.profile.name=inputValue(form,'name');S.profile.quote=inputValue(form,'quote')||defaultState().profile.quote;S.profile.avatar=await photoField(form,'avatar')||S.profile.avatar;S.profile.cover=await photoField(form,'cover')||S.profile.cover;await persist();closeDialog();toast('Perfil atualizado! 🌷')}
else if(type==='routineForm'){let id=inputValue(form,'id'),existing=S.routines.find(r=>r.id===id);let t={id:id||uid(),title:inputValue(form,'title'),category:inputValue(form,'category'),targetMinutes:Math.max(0,Number(inputValue(form,'targetMinutes'))||0),schedule:inputValue(form,'schedule'),start:inputValue(form,'start'),end:inputValue(form,'end')};if(!t.title)throw Error('Digite o nome da atividade.');if(existing)Object.assign(existing,t);else S.routines.push(t);await persist();closeDialog();toast('Atividade salva!')}
else if(type==='logForm'){let rid=inputValue(form,'routineId');if(!S.routines.some(r=>r.id===rid))throw Error('Atividade não encontrada.');let minutes=Number(inputValue(form,'minutes'));if(!Number.isFinite(minutes)||minutes<0||minutes>1440)throw Error('Digite minutos entre 0 e 1440.');let photo=await photoField(form,'photo');S.logs.push({id:uid(),routineId:rid,date:inputValue(form,'date')||today(),minutes,note:inputValue(form,'note'),photo,createdAt:new Date().toISOString()});await persist();closeDialog();toast('Registro salvo! Progresso atualizado. 🌷')}
else if(type==='noteForm'){let id=inputValue(form,'id'),data={id:id||uid(),title:inputValue(form,'title'),text:inputValue(form,'text'),updated:new Date().toISOString()},old=S.notes.find(x=>x.id===id);if(old)Object.assign(old,data);else S.notes.push(data);await persist();closeDialog();toast('Anotação salva!')}
else if(type==='dreamForm'){let id=inputValue(form,'id'),old=S.dreams.find(d=>d.id===id),data={id:id||uid(),title:inputValue(form,'title'),text:inputValue(form,'text'),photo:await photoField(form,'photo')||old?.photo||null};if(old)Object.assign(old,data);else S.dreams.push(data);await persist();closeDialog();toast('Sonho salvo no mural! 🌸')}
else if(type==='verseNoteForm'){S.bible.verseNotes??={};let k=inputValue(form,'key'),value=inputValue(form,'text');if(value.trim())S.bible.verseNotes[k]=value;else delete S.bible.verseNotes[k];await persist();closeDialog();toast('Anotação salva! 📖')}
else if(type==='slideForm'){S.slides.push({id:uid(),title:inputValue(form,'title'),text:inputValue(form,'text'),asset:await photoField(form,'photo')});slideIndex=S.slides.length-1;await persist();closeDialog();toast('Foto adicionada à tela inicial!')}
else if(type==='planForm'){let book=inputValue(form,'book'),from=Number(inputValue(form,'from')),to=Number(inputValue(form,'to')),item=B.find(x=>x[1]===book);if(!item||!Number.isInteger(from)||!Number.isInteger(to)||from<1||to<from||to>item[2])throw Error('Escolha capítulos válidos, em ordem crescente.');S.bible.plan[chosenBibleDay]={book,from,to};planFlow=null;await persist();closeDialog();toast('Leitura personalizada salva!')}
else if(type==='bookForm'){let id=inputValue(form,'id'),old=S.books.find(b=>b.id===id),file=form.elements.namedItem('file')?.files?.[0],asset=old?.asset,kind=old?.kind;if(file){let fn=file.name.toLowerCase();if(!fn.endsWith('.pdf')&&!fn.endsWith('.epub'))throw Error('Escolha PDF ou EPUB.');kind=fn.endsWith('.pdf')?'pdf':'epub';asset=await storeAsset(file)}if(!asset)throw Error('Escolha um arquivo.');let cover=await photoField(form,'cover')||old?.cover||null;let t=inputValue(form,'title')||file?.name.replace(/\.(pdf|epub)$/i,'')||'Livro';let data={id:id||uid(),title:t,author:inputValue(form,'author'),asset,kind,cover,status:inputValue(form,'status'),page:old?.page||1,pages:old?.pages||null,cfi:old?.cfi||null,percent:old?.percent||0,addedAt:old?.addedAt||new Date().toISOString()};if(old)Object.assign(old,data);else S.books.push(data);await persist();closeDialog();toast('Livro salvo na estante! 📚')}
}catch(e){console.error(e);toast('Não foi possível salvar: '+e.message)}}
async function onClick(e){let nav=e.target.closest('[data-nav]');if(nav){closeIfDialog();go(nav.dataset.nav);return}let slide=e.target.closest('[data-slide]');if(slide){slideIndex=Number(slide.dataset.slide);if(slideTimer)clearInterval(slideTimer);startSlides();return}let plan=e.target.closest('[data-plan-day]');if(plan){chosenBibleDay=plan.dataset.planDay;planFlow=null;render();return}let btn=e.target.closest('[data-action]');if(btn){await actionDo(btn.dataset.action,btn.dataset.id,btn)}}
function closeIfDialog(){if(!$('#dialog').hidden){$('#dialog').hidden=true;document.body.style.overflow='';activeBook=null;currentPdfDoc=null}}
async function onChange(e){let x=e.target;if(x.id==='routineDay'){selectedDate=x.value;let r=S.routines.find(a=>a.id===selectedRoutine);if(r){$('#view').innerHTML=logView(r);hydrateImages($('#view'))}}else if(x.id==='bibleVersion'){S.bible.version=x.value;await persist();if(section==='plano'&&planFlow)render();else render()}else if(x.id==='bibleBook'){setChapter(x.value,1)}else if(x.id==='bibleChapter'){setChapter(bibleBook,x.value)}else if(x.id==='planDone'){if(x.checked&&!S.bible.read.includes(chosenBibleDay))S.bible.read.push(chosenBibleDay);if(!x.checked)S.bible.read=S.bible.read.filter(d=>d!==chosenBibleDay);await persist();render()}else if(x.id==='readerPage'){let b=S.books.find(a=>a.id===activeBook);if(b&&b.kind==='pdf'&&currentPdfDoc){b.page=Math.max(1,Math.min(b.pages||1,Number(x.value)||1));await paintPdf(b)}}}
async function init(){try{await loadState();bibleBook=S.bible.book||'acts';bibleChapter=S.bible.chapter||15;render();}catch(e){console.error(e);$('#view').innerHTML=`<div class="empty"><span class="em">⚠️</span><h2>Não foi possível abrir o armazenamento local</h2><p>${esc(e.message)}. Abra o site em uma janela normal do navegador (não anônima), permita armazenamento e recarregue.</p></div>`;toast('Falha no armazenamento: '+e.message)}}
document.addEventListener('click',onClick);document.addEventListener('change',onChange);document.addEventListener('submit',async e=>{if(['profileForm','routineForm','logForm','noteForm','dreamForm','slideForm','planForm','bookForm','verseNoteForm'].includes(e.target.getAttribute('id'))){e.preventDefault();await handleForm(e.target)}});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#dialog').hidden)closeDialog()});init();
})();
